19	/**
20	 * App\Models\Prodcat
21	 *
22	 * @property int $onpage_id
23	 */
24	class Prodcat extends Model
25	{
26	    use CommonTrait;
27	    use OnPageTrait;
28	    use SoftDeletes;
29	    use HasFactory;
30	
31	    /**
32	     * revisionable configuration
33	     */
34	    use \Venturecraft\Revisionable\RevisionableTrait;
35	    protected $revisionForceDeleteEnabled = true;
36	    protected $revisionCreationsEnabled = true;
37	    protected $dontKeepRevisionOf = ['import_status'];
38	
39	
40	    /**
41	     * The table associated with the model.
42	     *
43	     * @var string
44	     */
45	    protected $table = 'prodcats';
46	
47	
48	    /**
49	     * The attributes that are mass assignable.
50	     *
51	     * @var array<int,string>
52	     */
53	    protected $fillable = [
54	        'item_id',
55	        'parent_id',
56	        'lang',
57	    ];
58	
59	
60	    public function langs(): HasMany
61	    {
62	        return $this->hasMany(ProdcatLang::class, "item_id");
63	    }
64	
65	
66	    /**
67	     * Disabilita auto annidamento nelle liste cms
68	     */
69	    public function hasNesting()
70	    {
71	        return false;
72	    }
73	
74	
75	    /**
76	     * Categoria superiore
77	     */
78	    public function parent(): BelongsTo
79	    {
80	        return $this->belongsTo(Prodcat::class);
81	    }
82	
83	    /**
84	     * Categorie figlie
85	     */
86	    public function children(): HasMany
87	    {
88	        return $this->hasMany(Prodcat::class, "parent_id");
89	    }
90	
91	
92	    /**
93	     * Scope per livello 0-based
94	     */
95	    public function scopeRoots(Builder $query): Builder
96	    {
97	        return $query->where(DB::raw('COALESCE(parent_id, 0)'), 0);
98	    }
99	
100	    public function scopeSubcategories(Builder $query): Builder
101	    {
102	        return $query->where(DB::raw('COALESCE(parent_id, 0)'), '<>', 0);
103	    }
104	
105	
106	    /**
107	     * Map remote OnPage fields to local ones.
108	     */
109	    public function onPageUpdateFromRemote(Thing $remoteItem, Resource $remoteResource): self
110	    {
111	        $this->onpage_resource = $remoteResource->name;
112	        $this->onpage_id = $remoteItem->id;
113	
114	        $this->onpage_raw = $this->collectFields($remoteItem, $remoteResource);
115	
116	        $this->save();
117	
118	        // create or update local subcategory lang
119	        foreach (config('marvin.locales') as $localeId =>  $localeInfo) {
120	            $localItemLang = ProdcatLang::firstOrNew([
121	                'lang' => $localeId,
122	                'item_id' => $this->id,
123	            ]);
124	
125	            $title = ucfirst(strtolower($remoteItem->val('nome', $localeInfo[0])));
126	
127	            // maps local attributes to remote ones
128	            $attributes = [
129	                'title' => $title,
130	                'page_url' => $localItemLang->page_url ?: Str::slug($title),
131	                'page_title' => $localItemLang->page_title ?: $title,
132	            ];
133	
134	            // by default, leave local data if any
135	            foreach ($attributes as $key => $remoteValue) {
136	                $localItemLang->$key = $remoteValue;
137	            }
138	
139	            $localItemLang->save();
140	        }
141	
142	
143	        return $this;
144	    }
145	
146	
147	    /**
148	     * Prodotti
149	     */
150	    public function products(): HasMany
151	    {
152	        return $this->hasMany(Product::class, 'prodcat_id');
153	    }
154	}
