3	namespace App\Http\Controllers;
4	
5	use App\Models\Prodcat;
6	use App\Models\ProdcatLang;
7	use App\Models\ProductVariant;
8	use App\Models\ProductVariantLang;
9	use App\Models\SearchIndex;
10	use App\Services\SearchService;
11	use AtrioTeam\Marvin\App\Localization\LangManager;
12	use AtrioTeam\Marvin\App\Localization\Router as MarvinRouter;
13	use Illuminate\Database\Eloquent\Relations\BelongsTo;
14	use Illuminate\Database\Eloquent\Relations\HasMany;
15	use Illuminate\Http\Request;
16	use Illuminate\Support\Facades\Cache;
17	use Venturecraft\Revisionable\Revision;
18	
19	class ProductsController extends Controller
20	{
21	    /**
22	     * Metodo dispatcher per gestire le richieste
23	     * e indirizzarle a categoria o prodotto a seconda
24	     * dell'ultimo segmento dell'url
25	     */
26	    public function dispatcher(Request $request, LangManager $langManager): mixed
27	    {
28	        $urls = explode('/', $request->categoryTree);
29	
30	        if (count($urls) == 3) {
31	            return $this->showProduct($request, $langManager, array_slice($urls, 0, -1), array_pop($urls));
32	        }
33	
34	        return $this->showCategory($request, $langManager, $urls);
35	
36	    }
37	
38	
39	    /**
40	     * Pagina Categoria / Sottocategoria
41	     */
42	    public function showCategory(Request $request, LangManager $langManager, array $categoriesUrls)
43	    {
44	        try {
45	            $request->validate([
46	                'page' => 'nullable|integer',
47	            ]);
48	        } catch (\Illuminate\Validation\ValidationException $e) {
49	            abort(400);
50	        }
51	
52	        $thisCategory = Prodcat::with('langs')
53	        ->byUrl($categoriesUrls[count($categoriesUrls) - 1], $langManager->lgId())
54	        ->published()
55	        // ->whereHas('parent', fn ($query) => $query->published())
56	        ->first();
57	
58	        if (!$thisCategory) {
59	            // verifico se esiste una revision per quell'url
60	            $revision = Revision::where([
61	                ['revisionable_type', ProdcatLang::class],
62	                ['key', 'page_url'],
63	                ['old_value', $request->getRequestUri()],
64	            ])->first();
65	            if ($revision?->new_value) {
66	                return redirect($revision?->new_value, 302);
67	            }
68	
69	            // nessun riscontro => 404
70	            abort(404);
71	        }
72	
73	        /**
74	         * recupero tutte le categorie
75	         */
76	        $categories = [];
77	        $currentCategory = null;
78	        foreach ($categoriesUrls as $k => $url) {
79	            $q = Prodcat::byUrl($url, $langManager->lgId());
80	            if ($currentCategory) {
81	                $q->where('parent_id', $currentCategory->id);
82	            }
83	            $currentCategory = $q->firstOrFail();
84	            $categories[] = $currentCategory;
85	
86	        }
87	
88	        // categoria a inizio albero, è quella di cui vengono mostrati i contenuti
89	        $thisCategory = reset($categories);
90	
91	        // tutte le sottocategorie
92	        $subcategories = $thisCategory->children()->listByLang($langManager->lgId())->get();
93	
94	        // sottocategoria corrente (potrebbe essere nulla)
95	        $thisSubcategory = count($categories) > 1 ? end($categories) : null;
96	
97	        // categoria per i metatag
98	        $metaCategory = $thisSubcategory ?: $thisCategory;
99	
100	        // se ho una sottocategoria, prendo i prodotti da quella, altrimenti dalle sottocategorie della categoria principale
101	        $prodcatIds = $thisSubcategory ? [$thisSubcategory->id] : $subcategories->pluck('id')->toArray();
102	
103	        /**
104	         * Recupero prodotti ed eseguo paginazione manuale, dopo aver ordinato la
105	         * collezione per posizione del parent senza farlo in fase di query.
106	         * Il recupero parte sempre dalle varianti perchè sono quelle che hanno il flag di pubblicazione.
107	         * Nella lista però vengono mostrati i prodotti.
108	         */
109	        $products = Cache::remember('category_products_'.implode('_', $prodcatIds).'_'.$langManager->lgId(), 60, function () use ($prodcatIds, $langManager) {
110	            return ProductVariant::published()->whereIn('prodcat_id', $prodcatIds)
111	               ->byLang($langManager->lgId())
112	               // @phpstan-ignore method.notFound
113	               ->whereHas('parent', fn ($query) => $query->published())
114	               // @phpstan-ignore method.notFound
115	               ->with('parent', fn (BelongsTo $query) => $query->byLang($langManager->lgId()))
116	               ->with('category')
117	               ->with('category.parent')
118	               ->get()
119	               ->sortBy('parent.position')
120	            ;
121	        });
122	        $count = $products->count();
123	
124	        // se ho richiesto una pagina, significa che ho premuto "carica altri",
125	        // per cui ritorno direttamente l'html con i nuovi contenuti
126	        if ((string)$request->js == '1') {
127	            $html = '';
128	            foreach ($products as $index => $product) {
129	                $html .= view("components.prodottoPreview", [
130	                    'product' => $product,
131	                    'index' => $index,
132	                    'grid' => true
133	                ])->render();
134	            }
135	
136	            return [
137	                'html' => $html,
138	            ];
139	        }
140	
141	        // elemento per alternates (v. ViewServiceProvider)
142	        $alternateItemSource = $thisSubcategory ?? $thisCategory;
143	
144	        return view('products.category', compact('thisCategory', 'subcategories', 'products', 'thisSubcategory', 'alternateItemSource', 'metaCategory'));
145	    }
