151	    public function showProduct(Request $request, LangManager $langManager, array $categoriesUrls, string $productUrl)
152	    {
153	
154	        /**
155	         * Recupero la variante
156	         */
157	        $thisVariant = ProductVariant::with('langs')
158	            ->byUrl($productUrl, $langManager->lgId())
159	            ->published()
160	            // @phpstan-ignore method.notFound
161	            ->whereHas('parent', fn ($query) => $query->published())
162	            ->first();
163	        if (!$thisVariant) {
164	            // verifico se esiste una revision per quell'url
165	            $revision = Revision::where([
166	                ['revisionable_type', ProductVariantLang::class],
167	                ['key', 'page_url'],
168	                ['old_value', $request->getRequestUri()],
169	            ])->first();
170	            if ($revision?->new_value) {
171	                return redirect($revision?->new_value, 302);
172	            }
173	
174	            // nessun riscontro => 404
175	            abort(404);
176	        }
177	
178	        /**
179	         * recupero tutte le categorie
180	         */
181	        $categories = [];
182	        $currentCategory = null;
183	        foreach ($categoriesUrls as $k => $url) {
184	            $q = Prodcat::byUrl($url, $langManager->lgId());
185	            if ($currentCategory) {
186	                $q->where('parent_id', $currentCategory->id);
187	            }
188	            $currentCategory = $q->first();
189	            if (!$currentCategory) {
190	                abort(404);
191	            }
192	            $categories[] = $currentCategory;
193	
194	        }
195	
196	
197	        // categoria a inizio albero, è quella di cui vengono mostrati i contenuti
198	        $thisCategory = reset($categories);
199	
200	        //  sottocategorie corrente
201	        $thisSubcategory = end($categories);
202	
203	        // verifico che sottocategoria coincida con quella del prodotto
204	        if (!$thisSubcategory->is($thisVariant->category)) {
205	            abort(404);
206	        }
207	
208	        // precarico relazioni (alcune su parent, altre direttamente sulla variante)
209	        $thisVariant->load([
210	            'parent' => function ($query) use ($langManager) {
211	                $query->byLang($langManager->lgId(), true)->published();
212	            },
213	            'parent.downloads' => function ($query) use ($langManager) {
214	                $query->reorder()->byParentLang($langManager->lgId(), true)->defaultSort();
215	            },
216	            'parent.designers' => function ($query) use ($langManager) {
217	                $query->byLang($langManager->lgId())->limit(3);
218	            },
219	            'parent.widgets' => function ($query) use ($langManager) {
220	                $query->listByLang($langManager->lgId());
221	            },
222	            'components' => function ($query) use ($langManager) {
223	                $query->byLang($langManager->lgId(), false);
224	            },
225	            'components.finishes' => function ($query) use ($langManager) {
226	                $query->byLang($langManager->lgId(), false);
227	            },
228	            'components.materials' => function ($query) use ($langManager) {
229	                $query->byLang($langManager->lgId(), false);
230	            }
231	        ]);
232	
233	        // prodotti correlati
234	        if ($thisVariant->onpage_family_id) {
235	            $relatedProducts = ProductVariant::listByLang($langManager->lgId())
236	                ->where('onpage_family_id', $thisVariant->onpage_family_id)
237	                ->where('id', '!=', $thisVariant->id)
238	                // @phpstan-ignore method.notFound
239	                ->whereHas('parent', fn ($query) => $query->published())
240	                ->get();
241	        } else {
242	            $relatedProducts = collect([]);
243	        }
244	
245	        // prodotti della stessa famiglia, riferiti al parent
246	        // NON considero pubblicazione, che è gestita solo per il prodotto principale,
247	        // quello di cui sto visualizzando il dettaglio
248	        $familyProducts = $thisVariant->parent
249	            ->familyProducts()
250	            // @phpstan-ignore method.notFound
251	            ->with('downloads', fn ($query) => $query->byParentLang($langManager->lgId())->defaultSort())
252	            ->orderBy('onpage_position')
253	            ->get();
254	
255	
256	        // creo collezione labelComponente => lista finiture
257	        $finishes = $thisVariant->components->groupBy('current_lang.title')->map(
258	            // estrapolo finiture uniche
259	            fn ($item) => $item->pluck('finishes')->flatten()->unique(fn ($f) => $f->id)
260	        );
261	        // come sopra
262	        $materials = $thisVariant->components->groupBy('current_lang.title')->map(fn ($item) => $item->pluck('materials')->flatten()->unique(fn ($f) => $f->id));
263	
264	        // elemento per alternates (v. ViewServiceProvider)
265	        $alternateItemSource = $thisVariant;
266	
267	        // dati strutturati schema.org
268	        $jsonLdContent = $thisVariant->toJsonLd($request->url());
269	
270	        // view
271	        return view("products.detail", array_merge(
272	            compact('thisVariant', 'thisCategory', 'thisSubcategory', 'relatedProducts', 'finishes', 'materials', 'alternateItemSource', 'familyProducts', 'jsonLdContent'),
273	            [
274	                'thisProduct' => $thisVariant->parent,
275	                'downloads' => $thisVariant->parent->downloads,
276	            ],
277	        ));
278	    }
