3	namespace App\Exceptions;
4	
5	use Exception;
6	use Throwable;
7	use App\Mail\ExceptionOccuredMail;
8	use Illuminate\Support\Facades\DB;
9	use Illuminate\Support\Facades\Log;
10	use Illuminate\Support\Facades\Mail;
11	use Illuminate\Foundation\Exceptions\Handler as ExceptionHandler;
12	
13	class Handler extends ExceptionHandler
14	{
15	    /**
16	     * A list of the exception types that are not reported.
17	     *
18	     * @var array
19	     */
20	    protected $dontReport = [
21	        'App\Http\Exceptions\ComingSoonException'
22	    ];
23	
24	    /**
25	     * A list of the inputs that are never flashed for validation exceptions.
26	     *
27	     * @var array
28	     */
29	    protected $dontFlash = [
30	        'password',
31	        'password_confirmation',
32	    ];
33	
34	    /**
35	     * Report or log an exception.
36	     *
37	     * @param  \Exception  $exception
38	     * @return void
39	     */
40	    public function report(Throwable $exception)
41	    {
42	        // log 404 errors
43	        $this->log404($exception);
44	
45	        // riporta sempre errore via mail se eccezione è idonea e se sono in produzione
46	        if (config("app.env") == 'production' && $this->shouldReport($exception)) {
47	            $this->sendEmail($exception);
48	        }
49	
50	        // metodo genitore, scrive anche log di Laravel
51	        parent::report($exception);
52	    }
53	
54	
55	    /**
56	     * Render an exception into an HTTP response.
57	     *
58	     * @param  \Illuminate\Http\Request  $request
59	     * @param  \Exception  $exception
60	     * @return \Illuminate\Http\Response
61	     */
62	    public function render($request, Throwable $exception)
63	    {
64	        if ($exception instanceof \Illuminate\Http\Exceptions\PostTooLargeException) {
65	            return response("Il file caricato è troppo pesante.", 500);
66	        }
67	
68	        // se app è in debug mode mostra pagina del logger (Whoops) con dettagli dell'errore,
69	        // altrimenti esegue il render della vista di errore corrispondente al codice di risposta
70	        return parent::render($request, $exception);
71	    }
72	
73	
74	    /**
75	     * Invia mail di notifica
76	     */
77	    protected function sendEmail(Throwable $exception)
78	    {
79	        $e = new ExceptionOccuredMail($exception->__toString());
80	
81	        $e->to(config("errors.alert_mail"))->subject("Errore sito - " . config("app.name"));
82	
83	        // invio mail con libreria default di Laravel
84	        try {
85	            Mail::send($e);
86	        } catch (Throwable $e) {
87	            echo "error sending mail " . $e->getMessage();
88	        }
89	
90	        return true;
91	    }
92	
93	
94	    /**
95	     * Log 404 errors
96	     */
97	    protected function log404(Throwable $exception): void
98	    {
99	        if (
100	            $exception instanceof \Illuminate\Database\Eloquent\ModelNotFoundException
101	            || (
102	                $exception instanceof \Symfony\Component\HttpKernel\Exception\NotFoundHttpException
103	                &&
104	                $exception->getStatusCode() == 404
105	            )
106	        ) {
107	
108	            try {
109	                DB::table('link_redirect')->updateOrInsert([
110	                    'link_old' => '/'.ltrim(request()->path(), '/'),
111	                ], [
112	                    'priority' => 0,
113	                    'created_at' => now(),
114	                ]);
115	            } catch (Throwable $dbException) {
116	                Log::channel('notfound')->error('Error storing 404', [
117	                    'url' => request()->path(),
118	                    'exception' => $dbException,
119	                    'previous' => $exception,
120	                ]);
121	            }
122	
123	        }
124	    }
125	}
