 * Inietta traduzioni da csv nel translator di laravel
 */
public function loadTrads($locale)
{
    // evito di caricare più volte le traduzioni
    if (array_key_exists($locale, $this->lines)) {
        return true;
    }

    $this->lines[$locale] = [];

    /**
     * caricamento da db
     */
    if (config('marvin.lang_source') === "database") {
        $trads = DB::table("lang_trad")->select()->get();
        foreach ($trads as $key => $value) {
            $key = $this->createTradKey($value->group_code, $value->code, (array)$value, $locale);

            $this->lines[$locale][$key] = $value->{"text_".$locale};

            Lang::addLines([
                $key => $this->lines[$locale][$key]
            ], $locale);
        }
    }


    /**
     * caricamento da csv
     */
    $sourceFile = base_path("resources/lang/vendor/marvin/trads.json");
    if (config('marvin.lang_source') === "file" && file_exists($sourceFile)) {
        $trads = json_decode(file_get_contents($sourceFile), true);
        if ($trads) {
            foreach ($trads as $key => $value) {
                $key = $this->createTradKey($value["group_code"], $value['code'], $value, $locale);

                $this->lines[$locale][$key] = $value["text_".$locale];
                Lang::addLines([
                    $key => $this->lines[$locale][$key]
                ], $locale);
            }
        }
    }

    return true;
}


