/**
 * Rotte legacy delle vecchie basi ("/prodotti" it, "/products" en/us) e "/kaleido",
 * verso la nuova base "/collezioni" (it) / "/collections" (en/us).
 * Le rotte categoria/dettaglio puntano al dispatcher, che emette il 301 verso l'URL canonico
 * (categorie via request_url/revision, prodotti via full_page_url); ricerca e kaleido sono
 * redirect diretti con preservazione del path.
 */
$legacyCollections = [
    ['locale' => 'it', 'old' => 'prodotti', 'new' => 'collezioni', 'search' => 'ricerca'],
    ['locale' => 'en', 'old' => 'products', 'new' => 'collections', 'search' => 'search'],
    ['locale' => 'us', 'old' => 'products', 'new' => 'collections', 'search' => 'search'],
];
foreach ($legacyCollections as $c) {
    Route::get("{$c['locale']}/{$c['old']}/{$c['search']}", fn () => redirect("/{$c['locale']}/{$c['new']}/{$c['search']}", 301));
    Route::get("{$c['locale']}/{$c['old']}/{categoryTree}", [ProductsController::class, 'dispatcher'])
        ->where('categoryTree', '([a-zA-Z0-9\/\-]+)');
    Route::get("{$c['locale']}/kaleido/{rest?}", fn ($rest = null) => redirect("/{$c['locale']}/{$c['new']}/kaleido".($rest ? '/'.$rest : ''), 301))
        ->where('rest', '.*');
}

