input.new_string:
/**
 * Ricalcola request_url quando page_url cambia.
 * Lo facciamo in save() PRIMA di parent::save() (e quindi prima che revisionable catturi i
 * campi dirty), così la modifica di request_url viene registrata come revision — usata dal
 * dispatcher per i redirect 301. (Nell'hook "saving" verrebbe impostato dopo la cattura.)
 */
public function save(array $options = [])
{
    if ($this->isDirty('page_url')) {
        $this->request_url = $this->buildFullUrl();
    }

    return parent::save($options);
}

