 * Titolo della collezione con il prefisso "Collezione" / "Collection" (tradotto),
 * incapsulato in uno <span> per lo styling. Il titolo in DB resta pulito: il prefisso
 * viene aggiunto solo nei punti di display che lo richiedono.
 * Metodo (non accessor) per poter accettare parametri.
 */
public function getTitleCollection(): HtmlString
{
    return new HtmlString('<span>'.e(__('global.collezione')).'</span> '.e((string) $this->title));
}

input.new_string:
 * Titolo della collezione con il prefisso "Collezione" / "Collection" (tradotto),
 * incapsulato in uno <span> per lo styling. Il titolo in DB resta pulito: il prefisso
 * viene aggiunto solo nei punti di display che lo richiedono.
 * Metodo (non accessor) per poter accettare parametri.
 *
 * @param bool $alternative se true e alternative_title è valorizzato, usa quello al posto di title.
 */
public function getTitleCollection(bool $alternative = false): HtmlString
{
    $title = ($alternative && $this->alternative_title) ? $this->alternative_title : $this->title;

    return new HtmlString('<span>'.e(__('global.collezione')).'</span> '.e((string) $title));
}

